2f\u093e\u0902\u0915\u0928\n\n---\n\n### 1. \u0935\u093f\u0938\u094d\u0924\u0943\u0924 \u0914\u091a\u093f\u0924\u094d\u092f \u0914\u0930 \u0935\u0948\u091c\u094d\u091e\u093e\u0928\u093f\u0915 \u092a\u0930\u093f\u0915\u0932\u094d\u092a\u0928\u093e (Rationale & Scientific Hypotheses)\n\n#### 1.1 \u0935\u0948\u091c\u094d\u091e\u093e\u0928\u093f\u0915 \u092a\u0943\u0937\u094d\u0920\u092d\u0942\u092e\u093f \u090f\u0935\u0902 \u0914\u091a\u093f\u0924\u094d\u092f\n\u092e\u0949\u0932\u093f\u0915\u094d\u092f\u0942\u0932\u0930 \u0921\u093e\u092f\u0928\u093e\u092e\u093f\u0915\u094d\u0938 (MD) \u0938\u093f\u092e\u0941\u0932\u0947\u0936\u0928 \u092e\u0947\u0902 \u092e\u0948\u0915\u094d\u0930\u094b\u092e\u0949\u0932\u093f\u0915\u094d\u092f\u0942\u0932\u094d\u0938 \u0915\u0947 \u0938\u092e\u092f-\u0906\u0927\u093e\u0930\u093f\u0924 \u0935\u094d\u092f\u0935\u0939\u093e\u0930 \u0915\u094b \u092b\u0947\u092e\u094d\u091f\u094b\u0938\u0947\u0915\u0902\u0921 ($\\sim 1\\text{--}2\\text{ fs}$) \u090f\u0915\u0940\u0915\u0930\u0923 \u091a\u0930\u0923\u094b\u0902 \u0915\u0947 \u0938\u093e\u0925 \u0939\u0932 \u0915\u093f\u092f\u093e \u091c\u093e\u0924\u093e \u0939\u0948\u0964 \u0921\u0947\u091f\u093e \u092d\u0902\u0921\u093e\u0930\u0923 \u0938\u0940\u092e\u093e\u0913\u0902 \u0915\u0947 \u0915\u093e\u0930\u0923, \u0907\u0928 \u091f\u094d\u0930\u0948\u091c\u0947\u0915\u094d\u091f\u0930\u0940\u091c\u093c \u0915\u094b \u0905\u0915\u094d\u0938\u0930 \u0938\u092c-\u0938\u0948\u0902\u092a\u0932 (\u0921\u093e\u0909\u0928\u0938\u0948\u0902\u092a\u0932) \u0915\u0930\u0915\u0947 \u092a\u093f\u0915\u094b\u0938\u0947\u0915\u0902\u0921 \u092f\u093e \u0928\u0948\u0928\u094b\u0938\u0947\u0915\u0902\u0921 \u0905\u0902\u0924\u0930\u093e\u0932 \u092a\u0930 \u0938\u0939\u0947\u091c\u093e \u091c\u093e\u0924\u093e \u0939\u0948\u0964 \u0907\u0938\u0915\u0947 \u092a\u0930\u093f\u0923\u093e\u092e\u0938\u094d\u0935\u0930\u0942\u092a, \u0909\u091a\u094d\u091a-\u0906\u0935\u0943\u0924\u094d\u0924\u093f \u0917\u0924\u093f\u0915\u0940\u2014\u0935\u093f\u0936\u0947\u0937\u0915\u0930 \u091f\u0949\u0930\u094d\u0936\u0928 \u090f\u0902\u0917\u0932 \u0911\u0938\u093f\u0932\u0947\u0936\u0928 (dihedral angle vibrations, 10\u2013300 cm$^{-1}$ / 0.3\u201310 THz) \u0914\u0930 \u092c\u0902\u0927 \u0915\u0902\u092a\u0928\u2014\u0928\u093e\u0907\u0915\u094d\u0935\u093f\u0938\u094d\u091f-\u0936\u0948\u0928\u0928 \u0938\u0948\u0902\u092a\u0932\u093f\u0902\u0917 \u0938\u0940\u092e\u093e \u0915\u0947 \u0915\u093e\u0930\u0923 \u092a\u0942\u0930\u0940 \u0924\u0930\u0939 \u0932\u0941\u092a\u094d\u0924 (aliased/lost) \u0939\u094b \u091c\u093e\u0924\u0947 \u0939\u0948\u0902\u0964 \n\n\u091c\u0928\u0930\u0947\u091f\u093f\u0935 \u0921\u0940\u092a \u0932\u0930\u094d\u0928\u093f\u0902\u0917 \u092e\u0949\u0921\u0932 \u091c\u0948\u0938\u0947 **MDGEN** \u0915\u094b \u0907\u0928 \u0917\u093e\u092f\u092c \u091f\u093e\u0907\u092e\u0938\u094d\u091f\u0947\u092a\u094d\u0938 \u0915\u094b \u0907\u0928\u092a\u0947\u0902\u091f \u092f\u093e \u0907\u0902\u091f\u0930\u092a\u094b\u0932\u0947\u091f \u0915\u0930\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u092a\u094d\u0930\u0938\u094d\u0924\u093e\u0935\u093f\u0924 \u0915\u093f\u092f\u093e \u0917\u092f\u093e \u0939\u0948\u0964 \u0915\u093f\u0902\u0924\u0941 \u092f\u0939 \u0938\u094d\u092a\u0937\u094d\u091f \u0928\u0939\u0940\u0902 \u0939\u0948 \u0915\u093f \u0915\u094d\u092f\u093e MDGEN \u0935\u093e\u0938\u094d\u0924\u0935 \u092e\u0947\u0902 \u0938\u0939\u0940 \u092d\u094c\u0924\u093f\u0915 \u0915\u0902\u092a\u0928 (physical vibrational modes) \u0914\u0930 \u0939\u093e\u0930\u094d\u092e\u094b\u0928\u093f\u0915/\u090f\u0928\u0939\u093e\u0930\u094d\u092e\u094b\u0928\u093f\u0915 \u0911\u0938\u093f\u0932\u0947\u0936\u0928 \u0930\u093f\u0915\u0935\u0930 \u0915\u0930 \u092a\u093e\u0924\u093e \u0939\u0948, \u0905\u0925\u0935\u093e \u092f\u0939 \u0915\u0947\u0935\u0932 \u090f\u0915 \u091a\u093f\u0915\u0928\u093e (over-smoothed) \u092a\u0925 \u092f\u093e \u0917\u0948\u0930-\u092d\u094c\u0924\u093f\u0915 \u092f\u093e\u0926\u0943\u091a\u094d\u091b\u093f\u0915 \u0936\u094b\u0930 (incoherent noise) \u0909\u0924\u094d\u092a\u0928\u094d\u0928 \u0915\u0930\u0924\u093e \u0939\u0948\u0964 \u0907\u0938 \u092a\u094d\u0930\u0936\u094d\u0928 \u0915\u093e \u0935\u094d\u092f\u0935\u0938\u094d\u0925\u093f\u0924 \u0909\u0924\u094d\u0924\u0930 \u0926\u0947\u0928\u093e \u092c\u093e\u092f\u094b\u092e\u094b\u0932\u0947\u0915\u094d\u092f\u0941\u0932\u0930 \u092e\u0949\u0921\u0932\u093f\u0902\u0917 \u092e\u0947\u0902 \u091c\u0928\u0930\u0947\u091f\u093f\u0935 \u092e\u0949\u0921\u0932\u094d\u0938 \u0915\u0940 \u0935\u093f\u0936\u094d\u0935\u0938\u0928\u0940\u092f\u0924\u093e \u0938\u094d\u0925\u093e\u092a\u093f\u0924 \u0915\u0930\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0906\u0935\u0936\u094d\u092f\u0915 \u0939\u0948\u0964\n\n#### 1.2 \u092a\u0930\u093f\u0915\u0932\u094d\u092a\u0928\u093e\u090f\u0902 (Hypotheses)\n* **\u0936\u0942\u0928\u094d\u092f \u092a\u0930\u093f\u0915\u0932\u094d\u092a\u0928\u093e ($H_0$):** MDGEN \u0938\u092c-\u0938\u0948\u0902\u092a\u0932\u094d\u0921 \u091f\u094d\u0930\u0948\u091c\u0947\u0915\u094d\u091f\u0930\u0940\u091c\u093c \u0938\u0947 \u0917\u093e\u092f\u092c \u092b\u093e\u0938\u094d\u091f \u091f\u093e\u0907\u092e\u0938\u094d\u091f\u0947\u092a \u0921\u093e\u092f\u0928\u093e\u092e\u093f\u0915\u094d\u0938 \u0915\u094b \u0938\u091f\u0940\u0915 \u0930\u0942\u092a \u0938\u0947 \u0930\u093f\u0915\u0935\u0930 \u0928\u0939\u0940\u0902 \u0915\u0930 \u092a\u093e\u0924\u093e \u0939\u0948; \u0909\u0924\u094d\u092a\u0928\u094d\u0928 \u091f\u0949\u0930\u094d\u0936\u0928 \u090f\u0902\u0917\u0932\u094d\u0938 \u0915\u093e \u092a\u093e\u0935\u0930 \u0938\u094d\u092a\u0947\u0915\u094d\u091f\u094d\u0930\u0932 \u0921\u0947\u0902\u0938\u093f\u091f\u0940 (PSD), \u0935\u0947\u0932\u094b\u0938\u093f\u091f\u0940 \u0911\u091f\u094b\u0915\u094b\u0930\u093f\u0932\u0947\u0936\u0928 (VACF), \u0914\u0930 \u0935\u093e\u0907\u092c\u094d\u0930\u0947\u0936\u0928\u0932 \u0921\u0947\u0902\u0938\u093f\u091f\u0940 \u0911\u092b \u0938\u094d\u091f\u0947\u091f\u094d\u0938 (VDOS) \u092c\u0947\u0938\u0932\u093e\u0907\u0928 \u0938\u094d\u092a\u094d\u0932\u093e\u0907\u0928 \u0907\u0902\u091f\u0930\u092a\u094b\u0932\u0947\u0936\u0928 \u092f\u093e \u0917\u0949\u0938\u093f\u092f\u0928 \u0938\u094d\u092e\u0942\u0925\u093f\u0902\u0917 \u0938\u0947 \u0938\u093e\u0902\u0916\u094d\u092f\u093f\u0915\u0940\u092f \u0930\u0942\u092a \u0938\u0947 \u092d\u093f\u0928\u094d\u0928/\u092c\u0947\u0939\u0924\u0930 \u0928\u0939\u0940\u0902 \u0939\u094b\u0924\u0947 \u0939\u0948\u0902 \u0914\u0930 \u0917\u094d\u0930\u093e\u0909\u0902\u0921 \u091f\u094d\u0930\u0941\u0925 \u0938\u0947 \u092e\u0939\u0924\u094d\u0935\u092a\u0942\u0930\u094d\u0923 \u0935\u093f\u091a\u0932\u0928 \u0926\u093f\u0916\u093e\u0924\u0947 \u0939\u0948\u0902 ($p > 0.05$)\u0964\n* **\u0935\u0948\u0915\u0932\u094d\u092a\u093f\u0915 \u092a\u0930\u093f\u0915\u0932\u094d\u092a\u0928\u093e ($H_1$):** MDGEN \u0932\u0941\u092a\u094d\u0924 \u092b\u093e\u0938\u094d\u091f \u091f\u093e\u0907\u092e\u0938\u094d\u091f\u0947\u092a \u0921\u093e\u092f\u0928\u093e\u092e\u093f\u0915\u094d\u0938 \u0915\u094b \u0909\u091a\u094d\u091a \u0936\u0941\u0926\u094d\u0927\u0924\u093e \u0915\u0947 \u0938\u093e\u0925 \u0930\u093f\u0915\u0935\u0930 \u0915\u0930\u0924\u093e \u0939\u0948; \u0907\u0938\u0915\u0947 \u0926\u094d\u0935\u093e\u0930\u093e \u0909\u0924\u094d\u092a\u0928\u094d\u0928 \u091f\u0949\u0930\u094d\u0936\u0928 \u090f\u0902\u0917\u0932 \u0911\u0938\u093f\u0932\u0947\u0936\u0928 \u0915\u0940 \u092a\u094d\u0930\u092e\u0941\u0916 \u0906\u0935\u0943\u0924\u094d\u0924\u093f\u092f\u093e\u0902 (peak frequencies), \u090f\u092e\u094d\u092a\u094d\u0932\u0940\u091f\u094d\u092f\u0942\u0921 \u0921\u093f\u0938\u094d\u091f\u094d\u0930\u0940\u092c\u094d\u092f\u0942\u0936\u0928, \u0914\u0930 \u0921\u0948\u092e\u094d\u092a\u093f\u0902\u0917 \u0926\u0930\u0947\u0902 \u0917\u094d\u0930\u093e\u0909\u0902\u0921 \u091f\u094d\u0930\u0941\u0925 \u0911\u0932-\u090f\u091f\u092e \u0938\u093f\u092e\u0941\u0932\u0947\u0936\u0928 \u0915\u0947 \u0905\u0928\u0941\u0930\u0942\u092a \u0939\u094b\u0924\u0940 \u0939\u0948\u0902 \u0914\u0930 \u091c\u0947\u0928\u094d\u0938\u0928-\u0936\u0948\u0928\u0928 \u0921\u093e\u0907\u0935\u0930\u094d\u091c\u0947\u0902\u0938 $JSD < 0.05$ \u092a\u094d\u0930\u0926\u0930\u094d\u0936\u093f\u0924 \u0915\u0930\u0924\u0940 \u0939\u0948\u0902\u0964\n\n---\n\n### 2. \u092a\u094d\u0930\u092f\u094b\u0917\u093e\u0924\u094d\u092e\u0915 \u092a\u094d\u0930\u0923\u093e\u0932\u0940 \u0914\u0930 \u0921\u0947\u091f\u093e\u0938\u0947\u091f \u0921\u093f\u091c\u093c\u093e\u0907\u0928 (Benchmark & Ground Truth Generation)\n\n#### 2.1 \u092e\u0949\u0921\u0932 \u0938\u093f\u0938\u094d\u091f\u092e\u094d\u0938 \u0915\u093e \u091a\u092f\u0928\n\u0905\u0927\u094d\u092f\u092f\u0928 \u092e\u0947\u0902 \u091c\u091f\u093f\u0932\u0924\u093e \u0915\u0947 \u0926\u094b \u0938\u094d\u0924\u0930\u094b\u0902 \u0935\u093e\u0932\u0947 \u0938\u093f\u0938\u094d\u091f\u092e \u0936\u093e\u092e\u093f\u0932 \u0939\u094b\u0902\u0917\u0947:\n1. **\u090f\u0932\u0947\u0928\u093f\u0928 \u0921\u093e\u0907\u092a\u0947\u092a\u094d\u091f\u093e\u0907\u0921 (Alanine Dipeptide, $Ac\\text{-}Ala\\text{-}NHMe$):** \u0935\u0948\u0915\u094d\u092f\u0942\u092e \u0924\u0925\u093e \u0938\u094d\u092a\u0937\u094d\u091f \u0935\u093f\u0932\u093e\u092f\u0915 (explicit TIP3P \u091c\u0932) \u0926\u094b\u0928\u094b\u0902 \u092e\u0947\u0902\u0964 \u0907\u0938\u092e\u0947\u0902 $\\phi$ \u0914\u0930 $\\psi$ \u0921\u093e\u092f\u0939\u0947\u0921\u094d\u0930\u0932\u094d\u0938 \u0915\u0940 \u092b\u093e\u0938\u094d\u091f \u0932\u093f\u092c\u094d\u0930\u0947\u0936\u0928 (fast torsional librations) \u0938\u094d\u092a\u0937\u094d\u091f \u0914\u0930 \u0917\u0923\u093f\u0924\u0940\u092f \u0930\u0942\u092a \u0938\u0947 \u0938\u0941\u092a\u0930\u093f\u092d\u093e\u0937\u093f\u0924 \u0939\u094b\u0924\u0940 \u0939\u0948\u0902\u0964\n2. **\u091a\u093f\u0917\u094d\u0928\u094b\u0932\u093f\u0928 \u092e\u093f\u0928\u0940-\u092a\u094d\u0930\u094b\u091f\u0940\u0928 (Chignolin, 10 residues, CLN025):** \u092c\u0948\u0915\u092c\u094b\u0928 \u0914\u0930 \u0938\u093e\u0907\u0921-\u091a\u0947\u0928 ($\\chi$) \u091f\u0949\u0930\u094d\u0936\u0928 \u090f\u0902\u0917\u0932\u094d\u0938 \u0915\u0947 \u091c\u091f\u093f\u0932 \u0928\u0947\u091f\u0935\u0930\u094d\u0915 \u092e\u0947\u0902 \u092b\u093e\u0938\u094d\u091f-\u091f\u093e\u0907\u092e\u0938\u094d\u091f\u0947\u092a \u0930\u093f\u0915\u0935\u0930\u0940 \u0915\u093e \u092a\u0930\u0940\u0915\u094d\u0937\u0923\u0964\n\n#### 2.2 \u0917\u094d\u0930\u093e\u0909\u0902\u0921 \u091f\u094d\u0930\u0941\u0925 \u0938\u093f\u092e\u0941\u0932\u0947\u0936\u0928 \u092a\u094d\u0930\u094b\u091f\u094b\u0915\u0949\u0932 ($T_{\\text{fine}}$)\n* **\u0907\u0902\u091c\u0928:** OpenMM 8.x / GROMACS 2024\n* **\u092b\u094b\u0930\u094d\u0938 \u092b\u0940\u0932\u094d\u0921:** AMBER ff19SB (\u092a\u094d\u0930\u094b\u091f\u0940\u0928) + OPC/TIP3P (\u091c\u0932)\n* **\u0907\u0902\u091f\u0940\u0917\u094d\u0930\u0947\u091f\u0930:** Langevin Leap-frog, \u0924\u093e\u092a\u092e\u093e\u0928 $T = 300\\text{ K}$, \u0918\u0930\u094d\u0937\u0923 \u0917\u0941\u0923\u093e\u0902\u0915 $\\gamma = 1.0\\text{ ps}^{-1}$\n* **\u091f\u093e\u0907\u092e\u0938\u094d\u091f\u0947\u092a:** $\\delta t = 1.0\\text{ fs}$ (\u092c\u0949\u0928\u094d\u0921 \u0938\u094d\u091f\u094d\u0930\u0947\u091a\u093f\u0902\u0917 \u092a\u0930 \u0915\u094b\u0908 \u0930\u093f\u091c\u093f\u0921 SHAKE/LINCS \u092c\u093e\u0927\u093e \u0928\u0939\u0940\u0902, \u0924\u093e\u0915\u093f \u0938\u092d\u0940 \u0909\u091a\u094d\u091a-\u0906\u0935\u0943\u0924\u094d\u0924\u093f \u0911\u0938\u093f\u0932\u0947\u0936\u0928 \u092e\u094c\u091c\u0942\u0926 \u0930\u0939\u0947\u0902)\u0964\n* **\u0938\u0947\u0935\u093f\u0902\u0917 \u0906\u0935\u0943\u0924\u094d\u0924\u093f:** \u092a\u094d\u0930\u0924\u094d\u092f\u0947\u0915 $10\\text{ fs}$ \u092a\u0930 \u0915\u094b\u0911\u0930\u094d\u0921\u093f\u0928\u0947\u091f\u094d\u0938 \u0914\u0930 \u0935\u0947\u0932\u094b\u0938\u093f\u091f\u0940 \u0938\u0939\u0947\u091c\u0940 \u091c\u093e\u090f\u0902\u0917\u0940 (Nyquist cutoff frequency $= 50\\text{ THz}$, \u091c\u094b \u091f\u0949\u0930\u094d\u0936\u0928 \u0914\u0930 \u092c\u0947\u0902\u0921\u093f\u0902\u0917 \u092e\u094b\u0921\u094d\u0938 \u0915\u094b \u092a\u0942\u0930\u0940 \u0924\u0930\u0939 \u0915\u0948\u092a\u094d\u091a\u0930 \u0915\u0930\u0924\u0940 \u0939\u0948)\u0964\n* **\u0938\u093f\u092e\u0941\u0932\u0947\u0936\u0928 \u0932\u0902\u092c\u093e\u0908:** \u090f\u0932\u0947\u0928\u093f\u0928 \u0921\u093e\u0907\u092a\u0947\u092a\u094d\u091f\u093e\u0907\u0921 \u0915\u0947 \u0932\u093f\u090f $500\\text{ ns}$ (5 \u0938\u094d\u0935\u0924\u0902\u0924\u094d\u0930 \u0930\u0947\u092a\u094d\u0932\u093f\u0915\u093e $\\times$ $100\\text{ ns}$), \u091a\u093f\u0917\u094d\u0928\u094b\u0932\u093f\u0928 \u0915\u0947 \u0932\u093f\u090f $100\\text{ ns}$\u0964\n\n#### 2.3 \u0928\u093f\u092f\u0902\u0924\u094d\u0930\u093f\u0924 \u0938\u092c-\u0938\u0948\u0902\u092a\u0932\u093f\u0902\u0917 ($T_{\\text{coarse}}$)\n\u0917\u094d\u0930\u093e\u0909\u0902\u0921 \u091f\u094d\u0930\u0941\u0925 \u091f\u094d\u0930\u0948\u091c\u0947\u0915\u094d\u091f\u0930\u0940 \u0915\u094b \u091a\u093e\u0930 \u0905\u0932\u0917-\u0905\u0932\u0917 \u0905\u0902\u0924\u0930\u093e\u0932\u094b\u0902 \u092a\u0930 \u0921\u093e\u0909\u0928-\u0938\u0948\u0902\u092a\u0932 \u0915\u093f\u092f\u093e \u091c\u093e\u090f\u0917\u093e:\n* $\\Delta t_1 = 0.5\\text{ ps}$ (\u092e\u0927\u094d\u092f\u092e \u0938\u092c-\u0938\u0948\u0902\u092a\u0932\u093f\u0902\u0917, $50\\times$)\n* $\\Delta t_2 = 1.0\\text{ ps}$ (\u092e\u093e\u0928\u0915 \u0938\u092c-\u0938\u0948\u0902\u092a\u0932\u093f\u0902\u0917, $100\\times$)\n* $\\Delta t_3 = 5.0\\text{ ps}$ (\u0909\u091a\u094d\u091a \u0938\u092c-\u0938\u0948\u0902\u092a\u0932\u093f\u0902\u0917, $500\\times$)\n* $\\Delta t_4 = 10.0\\text{ ps}$ (\u0905\u0924\u094d\u092f\u0927\u093f\u0915 \u0938\u092c-\u0938\u0948\u0902\u092a\u0932\u093f\u0902\u0917, $1000\\times$, \u091c\u0939\u093e\u0902 \u091f\u094d\u0930\u093e\u0902\u091c\u093f\u0936\u0928 \u0938\u094d\u091f\u0947\u091f\u094d\u0938 \u091b\u0942\u091f\u0928\u0947 \u0932\u0917\u0924\u0940 \u0939\u0948\u0902)\n\n---\n\n### 3. \u0928\u093f\u092f\u0902\u0924\u094d\u0930\u0923 \u0914\u0930 \u0924\u0941\u0932\u0928\u093e\u0924\u094d\u092e\u0915 \u092c\u0947\u0938\u0932\u093e\u0907\u0928\u094d\u0938 (Controls & Baselines)\n\n| \u0936\u094d\u0930\u0947\u0923\u0940 | \u0935\u093f\u0927\u093f / \u092e\u0949\u0921\u0932 | \u092d\u0942\u092e\u093f\u0915\u093e \u0914\u0930 \u0914\u091a\u093f\u0924\u094d\u092f |\n| :--- | :--- | :--- |\n| **\u092a\u0949\u091c\u093f\u091f\u093f\u0935 \u0915\u0902\u091f\u094d\u0930\u094b\u0932** | \u0905\u0928\u0938\u092c-\u0938\u0948\u0902\u092a\u0932\u094d\u0921 \u0917\u094d\u0930\u093e\u0909\u0902\u0921 \u091f\u094d\u0930\u0941\u0925 ($T_{\\text{fine}}$) | \u092b\u093e\u0938\u094d\u091f \u0921\u093e\u092f\u0928\u093e\u092e\u093f\u0915\u094d\u0938 (\u0911\u0938\u093f\u0932\u0947\u0936\u0928 \u0938\u094d\u092a\u0947\u0915\u094d\u091f\u094d\u0930\u092e, \u0915\u093e\u0907\u0928\u0947\u091f\u093f\u0915\u094d\u0938) \u0915\u0947 \u0932\u093f\u090f \u0938\u0948\u0926\u094d\u0927\u093e\u0902\u0924\u093f\u0915 \u0905\u092a\u0930-\u092c\u093e\u0909\u0902\u0921\u0964 |\n| **\u092b\u093f\u091c\u093f\u0915\u094d\u0938-\u092c\u0947\u0938\u094d\u0921 \u0915\u0902\u091f\u094d\u0930\u094b\u0932** | \u0936\u0949\u0930\u094d\u091f \u092c\u0930\u094d\u0938\u094d\u091f MD (Harmonic-restrained Burst MD) | \u0938\u092c-\u0938\u0948\u0902\u092a\u0932\u094d\u0921 \u092b\u094d\u0930\u0947\u092e\u094d\u0938 \u0915\u0947 \u092c\u0940\u091a \u0939\u093e\u0930\u094d\u092e\u094b\u0928\u093f\u0915 \u092a\u093e\u0925 \u092a\u0930 \u0938\u093f\u092e\u0941\u0932\u0947\u0936\u0928 \u091a\u0932\u093e\u0915\u0930 \u092d\u094c\u0924\u093f\u0915 \u0930\u0942\u092a \u0938\u0947 \u0938\u0939\u0940 \u0935\u093e\u0907\u092c\u094d\u0930\u0947\u0936\u0902\u0938 \u0909\u0924\u094d\u092a\u0928\u094d\u0928 \u0915\u0930\u0928\u093e\u0964 |\n| **\u0928\u0947\u0917\u0947\u091f\u093f\u0935 \u0915\u0902\u091f\u094d\u0930\u094b\u0932 1** | \u0915\u094d\u092f\u0942\u092c\u093f\u0915 \u0938\u094d\u092a\u094d\u0932\u093e\u0907\u0928 \u0907\u0902\u091f\u0930\u092a\u094b\u0932\u0947\u0936\u0928 (Cubic Spline) | \u092f\u0939 \u091c\u093e\u0902\u091a\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0915\u093f \u0915\u094d\u092f\u093e MDGEN \u0915\u0947\u0935\u0932 \u090f\u0915 \u0938\u094d\u092e\u0942\u0925 \u0928\u094d\u092f\u0942\u0928\u0924\u092e-\u090a\u0930\u094d\u091c\u093e \u0935\u0915\u094d\u0930 \u092c\u0928\u093e \u0930\u0939\u093e \u0939\u0948 (\u0936\u0942\u0928\u094d\u092f \u0939\u093e\u0908-\u092b\u093c\u094d\u0930\u0940\u0915\u094d\u0935\u0947\u0902\u0938\u0940 \u0938\u094d\u092a\u0947\u0915\u094d\u091f\u094d\u0930\u092e)\u0964 |\n| **\u0928\u0947\u0917\u0947\u091f\u093f\u0935 \u0915\u0902\u091f\u094d\u0930\u094b\u0932 2** | \u0928\u0949\u0907\u091c\u093c-\u0907\u0902\u091c\u0947\u0915\u094d\u091f\u0930 \u0938\u094d\u092a\u094d\u0932\u093e\u0907\u0928 (Noise-added Spline) | \u0938\u094d\u092a\u094d\u0932\u093e\u0907\u0928 \u092a\u0925 \u092a\u0930 \u0924\u093e\u092a\u092e\u093e\u0928-\u0905\u0928\u0941\u0915\u0942\u0932 \u0917\u0949\u0938\u093f\u092f\u0928 \u0928\u0949\u0907\u091c\u093c \u091c\u094b\u0921\u093c\u0928\u093e, \u092f\u0939 \u0926\u0947\u0916\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0915\u093f \u0915\u094d\u092f\u093e MDGEN \u0915\u0947\u0935\u0932 \u0905\u0935\u094d\u092f\u0935\u0938\u094d\u0925\u093f\u0924 \u0928\u0949\u0907\u091c\u093c \u091c\u094b\u0921\u093c \u0930\u0939\u093e \u0939\u0948 \u092f\u093e \u0938\u0941\u0938\u0902\u0917\u0924 \u092d\u094c\u0924\u093f\u0915 \u0911\u0938\u093f\u0932\u0947\u0936\u0928\u0964 |\n| **\u092a\u0930\u0940\u0915\u094d\u0937\u0923 \u092e\u0949\u0921\u0932** | **MDGEN** | $T_{\\text{coarse}}$ \u0915\u094b \u0907\u0928\u092a\u0941\u091f \u0915\u0947 \u0930\u0942\u092a \u092e\u0947\u0902 \u0932\u0947\u0915\u0930 $10\\text{ fs}$ \u0930\u093f\u091c\u093c\u0949\u0932\u094d\u092f\u0942\u0936\u0928 \u092a\u0930 \u0907\u0902\u091f\u0930\u092a\u094b\u0932\u0947\u091f\u0947\u0921 \u092b\u094d\u0930\u0947\u092e \u091c\u0928\u0930\u0947\u091f \u0915\u0930\u0928\u093e\u0964 |\n\n---\n\n### 4. \u0938\u0902\u092a\u0942\u0930\u094d\u0923 \u0935\u093f\u0936\u094d\u0932\u0947\u0937\u0923 \u092f\u094b\u091c\u0928\u093e \u0914\u0930 \u092e\u0942\u0932\u094d\u092f\u093e\u0902\u0915\u0928 \u092e\u0947\u091f\u094d\u0930\u093f\u0915\u094d\u0938 (Detailed Analysis Plan & Evaluation Metrics)\n\n#### 4.1 \u092b\u094d\u0930\u0940\u0915\u094d\u0935\u0947\u0902\u0938\u0940 \u0921\u094b\u092e\u0947\u0928 \u090f\u0935\u0902 \u0938\u094d\u092a\u0947\u0915\u094d\u091f\u094d\u0930\u0932 \u0935\u093f\u0936\u094d\u0932\u0947\u0937\u0923 (Spectral Analysis)\n\u091f\u0949\u0930\u094d\u0936\u0928 \u090f\u0902\u0917\u0932\u094d\u0938 $\\theta(t) \\in \\{\\phi, \\psi, \\chi\\}$ \u0915\u0947 \u0938\u092e\u092f-\u0936\u094d\u0930\u0943\u0902\u0916\u0932\u093e \u0921\u0947\u091f\u093e \u0915\u093e \u0935\u093f\u0936\u094d\u0932\u0947\u0937\u0923:\n1. **\u092a\u093e\u0935\u0930 \u0938\u094d\u092a\u0947\u0915\u094d\u091f\u094d\u0930\u0932 \u0921\u0947\u0902\u0938\u093f\u091f\u0940 (Power Spectral Density - PSD):**\n   $$S_\\theta(\\omega) = \\lim_{T \\to \\infty} \\frac{1}{T} \\left| \\int_0^T (\\theta(t) - \\bar{\\theta}) e^{-i \\omega t} dt \\right|^2$$\n   * **\u092e\u0942\u0932\u094d\u092f\u093e\u0902\u0915\u0928:** \u0915\u094d\u092f\u093e $5\\text{ THz}$ \u0938\u0947 $30\\text{ THz}$ \u0915\u0947 \u092e\u0927\u094d\u092f \u0938\u094d\u0925\u093f\u0924 \u0935\u093f\u0936\u093f\u0937\u094d\u091f \u091f\u0949\u0930\u094d\u0936\u0928\u0932 \u0932\u093f\u092c\u094d\u0930\u0947\u0936\u0928\u0932 \u092a\u0940\u0915\u094d\u0938 MDGEN \u091f\u094d\u0930\u0948\u091c\u0947\u0915\u094d\u091f\u0930\u0940 \u092e\u0947\u0902 \u0938\u091f\u0940\u0915 \u0906\u0935\u0943\u0924\u094d\u0924\u093f ($\\omega_0$) \u0914\u0930 \u090f\u092e\u094d\u092a\u094d\u0932\u0940\u091f\u094d\u092f\u0942\u0921 \u0915\u0947 \u0938\u093e\u0925 \u0909\u092a\u0938\u094d\u0925\u093f\u0924 \u0939\u0948\u0902?\n2. **\u0935\u093e\u0907\u092c\u094d\u0930\u0947\u0936\u0928\u0932 \u0921\u0947\u0902\u0938\u093f\u091f\u0940 \u0911\u092b \u0938\u094d\u091f\u0947\u091f\u094d\u0938 (VDOS) \u0914\u0930 VACF:**\n   * \u0935\u0947\u0932\u094b\u0938\u093f\u091f\u0940 \u0911\u091f\u094b\u0915\u094b\u0930\u093f\u0932\u0947\u0936\u0928 \u092b\u093c\u0902\u0915\u094d\u0936\u0928:\n     $$C_v(t) = \\frac{\\langle \\mathbf{v}(0) \\cdot \\mathbf{v}(t) \\rangle}{\\langle \\mathbf{v}(0) \\cdot \\mathbf{v}(0) \\rangle}$$\n   * $C_v(t)$ \u0915\u093e \u092b\u0942\u0930\u093f\u092f\u0930 \u091f\u094d\u0930\u093e\u0902\u0938\u092b\u0949\u0930\u094d\u092e \u0932\u0947\u0915\u0930 VDOS \u0938\u094d\u092a\u0947\u0915\u094d\u091f\u094d\u0930\u092e \u092a\u094d\u0930\u093e\u092a\u094d\u0924 \u0915\u0930\u0928\u093e \u0914\u0930 \u0917\u094d\u0930\u093e\u0909\u0902\u0921 \u091f\u094d\u0930\u0941\u0925 \u0938\u094d\u092a\u0947\u0915\u094d\u091f\u094d\u0930\u092e \u0915\u0947 \u0938\u093e\u0925 \u0938\u094d\u092a\u0947\u0915\u094d\u091f\u094d\u0930\u0932 \u0913\u0935\u0930\u0932\u0948\u092a \u0917\u0941\u0923\u093e\u0902\u0915 ($S_{\\text{overlap}}$) \u092e\u093e\u092a\u0928\u093e:\n     $$S_{\\text{overlap}} = \\frac{\\int \\min(VDOS_{\\text{MDGEN}}(\\omega), VDOS_{\\text{True}}(\\omega)) d\\omega}{\\int VDOS_{\\text{True}}(\\omega) d\\omega}$$\n\n#### 4.2 \u0915\u093e\u0907\u0928\u0947\u091f\u093f\u0915 \u0914\u0930 \u0911\u091f\u094b\u0915\u094b\u0930\u093f\u0932\u0947\u0936\u0928 \u092e\u0947\u091f\u094d\u0930\u093f\u0915\u094d\u0938 (Time-Correlation Metrics)\n1. **\u091f\u0949\u0930\u094d\u0936\u0928 \u090f\u0902\u0917\u0932 \u0911\u091f\u094b\u0915\u094b\u0930\u093f\u0932\u0947\u0936\u0928 \u092b\u093c\u0902\u0915\u094d\u0936\u0928 (TACF):**\n   $$C_\\theta(\\tau) = \\frac{\\langle (\\theta(t) - \\bar{\\theta})(\\theta(t+\\tau) - \\bar{\\theta})\\rangle}{\\sigma_\\theta^2}$$\n   * \u0907\u0938\u0915\u0947 \u0921\u093f\u0915\u0949\u092f \u091f\u093e\u0907\u092e-\u0915\u093e\u0902\u0938\u094d\u091f\u0947\u0902\u091f ($\\tau_{\\text{decay}}$) \u0915\u0940 \u0924\u0941\u0932\u0928\u093e \u0915\u0930\u0928\u093e, \u0924\u093e\u0915\u093f \u092f\u0939 \u0938\u0941\u0928\u093f\u0936\u094d\u091a\u093f\u0924 \u0939\u094b \u0938\u0915\u0947 \u0915\u093f \u0915\u0902\u092a\u0928 \u0915\u093e \u0921\u0948\u092e\u094d\u092a\u093f\u0902\u0917 \u092c\u093f\u0939\u0947\u0935\u093f\u092f\u0930 \u092d\u094c\u0924\u093f\u0915 \u0939\u0948\u0964\n2. **\u0907\u0928\u094d\u0938\u091f\u0947\u0902\u091f\u0947\u0928\u093f\u092f\u0938 \u090f\u0902\u0917\u0941\u0932\u0930 \u0935\u0947\u0932\u094b\u0938\u093f\u091f\u0940 \u0921\u093f\u0938\u094d\u091f\u094d\u0930\u0940\u092c\u094d\u092f\u0942\u0936\u0928:**\n   * \u0915\u094b\u0923\u0940\u092f \u0935\u0947\u0917 $\\omega_\\theta(t) = \\frac{d\\theta}{dt}$ \u0915\u093e \u092e\u0948\u0915\u094d\u0938\u0935\u0947\u0932-\u092c\u094b\u0932\u094d\u091f\u094d\u091c\u093c\u092e\u093e\u0928 \u0935\u093f\u0924\u0930\u0923 \u0938\u0947 \u0935\u093f\u091a\u0932\u0928 \u091c\u093e\u0901\u091a\u0928\u093e (\u0915\u0941\u0930\u094d\u091f\u094b\u0938\u093f\u0938 \u0914\u0930 \u0938\u094d\u0915\u0947\u0935\u0928\u0947\u0938 \u091f\u0947\u0938\u094d\u091f)\u0964\n\n#### 4.3 \u0938\u0902\u0930\u091a\u0928\u093e\u0924\u094d\u092e\u0915 \u0905\u0916\u0902\u0921\u0924\u093e \u0914\u0930 \u0925\u0930\u094d\u092e\u094b\u0921\u093e\u092f\u0928\u093e\u092e\u093f\u0915 \u0915\u0902\u0938\u093f\u0938\u094d\u091f\u0947\u0902\u0938\u0940\n1. **\u0938\u094d\u091f\u0947\u0930\u093f\u0915 \u0915\u094d\u0932\u0948\u0936 \u0914\u0930 \u0917\u0948\u0930-\u092d\u094c\u0924\u093f\u0915 \u0938\u0902\u0930\u091a\u0928\u093e\u090f\u0902:**\n   * \u091c\u0928\u0930\u0947\u091f \u0915\u093f\u090f \u0917\u090f \u092b\u094d\u0930\u0947\u092e\u094d\u0938 \u092e\u0947\u0902 \u0935\u0948\u0928 \u0921\u0930 \u0935\u093e\u0932\u094d\u0938 \u0913\u0935\u0930\u0932\u0948\u092a\u094d\u0938 ($r_{ij} < 0.7 \\times (\\sigma_i + \\sigma_j)$) \u0914\u0930 \u092c\u0949\u0928\u094d\u0921 \u0932\u0947\u0902\u0917\u094d\u0925 \u0935\u093f\u0930\u0942\u092a\u0923 ($> 0.15\\text{ \\AA}$) \u0915\u0940 \u0917\u0923\u0928\u093e\u0964\n2. **\u0915\u0928\u094d\u092b\u0930\u094d\u092e\u0947\u0936\u0928\u0932 \u0921\u093f\u0938\u094d\u091f\u094d\u0930\u0940\u092c\u094d\u092f\u0942\u0936\u0928 (Ramachandran Divergence):**\n   * $\\phi\\text{--}\\psi$ \u0938\u094d\u092a\u0947\u0938 \u092e\u0947\u0902 2D \u092a\u094d\u0930\u094b\u092c\u0947\u092c\u093f\u0932\u093f\u091f\u0940 \u0921\u0947\u0902\u0938\u093f\u091f\u0940 $P(\\phi, \\psi)$ \u092c\u0928\u093e\u0915\u0930 Jensen-Shannon Divergence ($JSD$) \u0914\u0930 Wasserstein-1 \u0926\u0942\u0930\u0940 \u0928\u093f\u0915\u093e\u0932\u0928\u093e:\n     $$JSD(P_{\\text{MDGEN}} \\parallel P_{\\text{True}}) \\le 0.05$$\n\n#### 4.4 \u0938\u093e\u0902\u0916\u094d\u092f\u093f\u0915\u0940\u092f \u0915\u0920\u094b\u0930\u0924\u093e (Statistical Rigor)\n* \u092a\u094d\u0930\u0924\u094d\u092f\u0947\u0915 \u092a\u094d\u0930\u092f\u094b\u0917 \u0915\u094b 5 \u0938\u094d\u0935\u0924\u0902\u0924\u094d\u0930 \u092c\u0940\u091c\u094b\u0902 (random seeds / simulation replicas) \u0915\u0947 \u0938\u093e\u0925 \u0926\u094b\u0939\u0930\u093e\u092f\u093e \u091c\u093e\u090f\u0917\u093e\u0964\n* \u090f\u0930\u0930 \u092c\u093e\u0930\u094d\u0938 \u0914\u0930 95% \u0915\u0949\u0928\u094d\u092b\u093f\u0921\u0947\u0902\u0938 \u0907\u0902\u091f\u0930\u0935\u0932\u094d\u0938 \u092c\u094d\u0932\u0949\u0915-\u090f\u0935\u0930\u0947\u091c\u093f\u0902\u0917 \u0914\u0930 \u092c\u0942\u091f\u0938\u094d\u091f\u094d\u0930\u0948\u092a\u093f\u0902\u0917 ($B = 1000$) \u0926\u094d\u0935\u093e\u0930\u093e \u0928\u093f\u0930\u094d\u0927\u093e\u0930\u093f\u0924 \u0915\u093f\u090f \u091c\u093e\u090f\u0902\u0917\u0947\u0964\n* \u0917\u094d\u0930\u093e\u0909\u0902\u0921 \u091f\u094d\u0930\u0941\u0925 \u0914\u0930 MDGEN \u0915\u0947 \u092e\u0927\u094d\u092f \u0905\u0902\u0924\u0930 \u0915\u0940 \u092e\u0939\u0924\u094d\u0924\u093e \u092a\u0930\u0916\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u091f\u0942-\u0938\u0948\u0902\u092a\u0932 Kolmogorov-Smirnov (KS) \u091f\u0947\u0938\u094d\u091f ($p < 0.01$ \u092a\u0930 \u0905\u0938\u094d\u0935\u0940\u0915\u0943\u0924\u093f) \u0932\u093e\u0917\u0942 \u0915\u093f\u092f\u093e \u091c\u093e\u090f\u0917\u093e\u0964\n\n---\n\n### 5. \u0935\u094d\u092f\u093e\u0935\u0939\u093e\u0930\u093f\u0915\u0924\u093e, \u0915\u092e\u094d\u092a\u094d\u092f\u0942\u091f \u092c\u091c\u091f \u0914\u0930 \u0938\u0940\u092e\u093e\u090f\u0902 (Feasibility, Compute & Limitations)\n\n#### 5.1 \u0915\u092e\u094d\u092a\u094d\u092f\u0942\u091f \u0935\u094d\u092f\u0935\u0939\u093e\u0930\u094d\u092f\u0924\u093e \u0914\u0930 \u092c\u091c\u091f\n* **MD \u0938\u093f\u092e\u0941\u0932\u0947\u0936\u0928:** OpenMM \u0915\u093e \u0909\u092a\u092f\u094b\u0917 \u0915\u0930\u0924\u0947 \u0939\u0941\u090f 1x NVIDIA RTX 4090 \u092f\u093e A100 GPU \u092a\u0930 $100\\text{ ns}$ \u090f\u0932\u0947\u0928\u093f\u0928 \u0921\u093e\u0907\u092a\u0947\u092a\u094d\u091f\u093e\u0907\u0921 \u0938\u093f\u092e\u0941\u0932\u0947\u0936\u0928 \u092e\u0947\u0902 $\\sim 4$ \u0918\u0902\u091f\u0947 \u0932\u0917\u0924\u0947 \u0939\u0948\u0902\u0964 \u091a\u093f\u0917\u094d\u0928\u094b\u0932\u093f\u0928 \u0915\u0947 \u0932\u093f\u090f $\\sim 12$ \u0918\u0902\u091f\u0947\u0964 \u0915\u0941\u0932 MD \u0909\u0924\u094d\u092a\u093e\u0926\u0928 \u0938\u092e\u092f $\\approx 30\\text{ GPU-hours}$\u0964\n* **MDGEN \u0907\u0928\u094d\u092b\u0930\u0947\u0902\u0938:** 10,000 \u0938\u092c-\u0938\u0948\u0902\u092a\u0932\u094d\u0921 \u092b\u094d\u0930\u0947\u092e\u094d\u0938 \u0915\u0947 \u092c\u0940\u091a \u092b\u093e\u0907\u0928 \u092b\u094d\u0930\u0947\u092e\u094d\u0938 \u091c\u0928\u0930\u0947\u091f \u0915\u0930\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0921\u093f\u092b\u094d\u092f\u0942\u091c\u0928 \u0907\u0928\u094d\u092b\u0930\u0947\u0902\u0938 \u091f\u093e\u0907\u092e $\\approx 8\\text{ GPU-hours}$\u0964\n* **\u0935\u093f\u0936\u094d\u0932\u0947\u0937\u0923 \u092a\u093e\u0907\u092a\u0932\u093e\u0907\u0928:** MDAnalysis / MDTraj \u0914\u0930 SciPy/PyTorch \u0915\u093e \u0909\u092a\u092f\u094b\u0917 \u0915\u0930\u0924\u0947 \u0939\u0941\u090f PSD/VDOS \u0917\u0923\u0928\u093e $\\approx 2$ \u0918\u0902\u091f\u0947 (CPU-\u0906\u0927\u093e\u0930\u093f\u0924)\u0964\n* \u0905\u0924\u0903 \u092f\u0939 \u092a\u0942\u0930\u093e \u092a\u094d\u0930\u092f\u094b\u0917 \u090f\u0915 \u0938\u093e\u092e\u093e\u0928\u094d\u092f \u090f\u0915\u0932-\u0928\u094b\u0921 \u0935\u0930\u094d\u0915\u0938\u094d\u091f\u0947\u0936\u0928 \u092a\u0930 2\u20133 \u0926\u093f\u0928\u094b\u0902 \u092e\u0947\u0902 \u0938\u0941\u0917\u092e\u0924\u093e \u0938\u0947 \u0938\u0902\u092a\u0928\u094d\u0928 \u0915\u093f\u092f\u093e \u091c\u093e \u0938\u0915\u0924\u093e \u0939\u0948\u0964\n\n#### 5.2 \u092a\u094d\u0930\u092f\u094b\u0917\u093e\u0924\u094d\u092e\u0915 \u0938\u0940\u092e\u093e\u090f\u0902 (Limitations)\n1. **\u0938\u092c-\u0938\u0948\u0902\u092a\u0932\u093f\u0902\u0917 \u0938\u0940\u092e\u093e (Subsampling Threshold):** \u092f\u0926\u093f $\\Delta t_{\\text{coarse}}$ \u0938\u093f\u0938\u094d\u091f\u092e \u0915\u0947 \u0928\u094d\u092f\u0942\u0928\u0924\u092e \u092e\u0947\u091f\u093e\u0938\u094d\u091f\u0947\u092c\u0932 \u0938\u094d\u091f\u0947\u091f \u091f\u094d\u0930\u093e\u0902\u091c\u093f\u0936\u0928 \u091f\u093e\u0907\u092e \u0938\u0947 \u092c\u0921\u093c\u093e \u0939\u094b \u091c\u093e\u0924\u093e \u0939\u0948 (\u0909\u0926\u093e. $\\Delta t > 20\\text{ ps}$), \u0924\u094b \u0926\u094b \u092b\u094d\u0930\u0947\u092e\u094d\u0938 \u0915\u0947 \u092c\u0940\u091a \u0915\u0908 \u0938\u0902\u092d\u093e\u0935\u093f\u0924 \u092a\u0925 \u0939\u094b \u0938\u0915\u0924\u0947 \u0939\u0948\u0902\u0964 \u0910\u0938\u0940 \u0938\u094d\u0925\u093f\u0924\u093f \u092e\u0947\u0902 MDGEN \u090f\u0915 \u0928\u093f\u0930\u094d\u0927\u093e\u0930\u0915 \u0907\u0902\u091f\u0930\u092a\u094b\u0932\u0947\u091f\u0930 \u0928 \u0930\u0939\u0915\u0930 \u0938\u094d\u091f\u094b\u0915\u0947\u0938\u094d\u091f\u093f\u0915 \u092a\u093e\u0925 \u0938\u0948\u0902\u092a\u0932\u0930 \u092c\u0928 \u091c\u093e\u0924\u093e \u0939\u0948\u0964\n2. **\u0936\u093e\u0938\u094d\u0924\u094d\u0930\u0940\u092f (Classical) \u092c\u0928\u093e\u092e \u0915\u094d\u0935\u093e\u0902\u091f\u092e \u0915\u0902\u092a\u0928:** \u092b\u0947\u092e\u094d\u091f\u094b\u0938\u0947\u0915\u0902\u0921 \u0938\u094d\u0915\u0947\u0932 \u092a\u0930 \u092c\u0949\u0928\u094d\u0921 \u0915\u0902\u092a\u0928 (\u0909\u0926\u093e. $O\\text{-}H$ \u092f\u093e $C\\text{-}H$ \u0938\u094d\u091f\u094d\u0930\u0947\u091a\u093f\u0902\u0917 $> 3000\\text{ cm}^{-1}$) \u0915\u094d\u0935\u093e\u0902\u091f\u092e \u092a\u094d\u0930\u092d\u093e\u0935\u094b\u0902 \u0938\u0947 \u092a\u094d\u0930\u092d\u093e\u0935\u093f\u0924 \u0939\u094b\u0924\u0947 \u0939\u0948\u0902\u0964 \u091a\u0942\u0902\u0915\u093f \u0936\u093e\u0938\u094d\u0924\u094d\u0930\u0940\u092f MD \u092c\u0932 \u0915\u094d\u0937\u0947\u0924\u094d\u0930 \u0907\u0928\u094d\u0939\u0947\u0902 \u0939\u093e\u0930\u094d\u092e\u094b\u0928\u093f\u0915 \u0911\u0938\u093f\u0932\u0947\u091f\u0930 \u092e\u093e\u0928\u0924\u0947 \u0939\u0948\u0902, \u092f\u0939 \u0905\u0927\u094d\u092f\u092f\u0928 \u092e\u0941\u0916\u094d\u092f \u0930\u0942\u092a \u0938\u0947 \u091f\u0949\u0930\u094d\u0936\u0928 \u090f\u0902\u0917\u0932\u094d\u0938 \u0914\u0930 \u0928\u0949\u0928-\u092c\u0949\u0928\u094d\u0921\u0947\u0921 \u0915\u0932\u0947\u0915\u094d\u091f\u093f\u0935 \u092e\u094b\u0921\u094d\u0938 ($< 500\\text{ cm}^{-1}$) \u092a\u0930 \u0915\u0947\u0902\u0926\u094d\u0930\u093f\u0924 \u0930\u0939\u0947\u0917\u093e, \u091c\u0939\u093e\u0902 \u0936\u093e\u0938\u094d\u0924\u094d\u0930\u0940\u092f \u092d\u094c\u0924\u093f\u0915\u0940 \u092a\u0942\u0930\u094d\u0923\u0924\u0903 \u092e\u093e\u0928\u094d\u092f \u0939\u0948\u0964", "summary": "MDGEN \u0926\u094d\u0935\u093e\u0930\u093e \u092b\u093e\u0938\u094d\u091f \u091f\u093e\u0907\u092e\u0938\u094d\u091f\u0947\u092a \u0921\u093e\u092f\u0928\u093e\u092e\u093f\u0915\u094d\u0938 \u0930\u093f\u0915\u0935\u0930\u0940 \u0915\u0940 \u091c\u093e\u0902\u091a \u0939\u0947\u0924\u0941 \u0938\u0902\u092a\u0942\u0930\u094d\u0923 \u090f\u0915\u094d\u0938\u092a\u0947\u0930\u093f\u092e\u0947\u0902\u091f \u0921\u093f\u091c\u093c\u093e\u0907\u0928 (\u0914\u091a\u093f\u0924\u094d\u092f, \u0915\u0902\u091f\u094d\u0930\u094b\u0932\u094d\u0938, \u0935\u093f\u0936\u094d\u0932\u0947\u0937\u0923 \u092f\u094b\u091c\u0928\u093e \u0914\u0930 \u0938\u0940\u092e\u093e\u090f\u0902) \u092a\u094d\u0930\u0938\u094d\u0924\u0941\u0924 \u0915\u093f\u092f\u093e \u0917\u092f\u093e\u0964"}", "origin": "completion"}, "llm_response_id": "RebTatXiHt2nq8YP9rjboQw", "security_risk": "UNKNOWN", "kind": "ActionEvent", "source_event_index": 11}
